using System.Text;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

// --- Configuration ---
// Set your API key via environment variable: OPENAI_API_KEY
// Optionally set model via: OPENAI_MODEL (defaults to gpt-4o-mini-2024-07-18)
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL")
    ?? "gpt-4o-mini-2024-07-18";

// --- Register services ---
builder.Services.AddHttpClient<WebSearchTool>();

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, apiKey));

builder.Services.AddSingleton<NoteTool>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var webSearch = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();

// --- Build tools list ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(webSearch.FetchPageContentAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
    AIFunctionFactory.Create(noteTool.GetNoteSummary),
};

// --- Create the research agent ---
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to thoroughly research a topic provided by the user.

        Follow this workflow:
        1. Search the web for the topic using multiple varied queries to get broad coverage.
        2. Fetch and read the most promising pages to gather detailed information.
        3. Save key findings as notes using the note-taking tool, categorizing them by topic
           (e.g., "definition", "history", "key finding", "statistic", "expert opinion").
           Always include the source URL when saving notes.
        4. After gathering enough information (at least 5-8 notes), retrieve all your notes
           and synthesize them into a comprehensive summary.

        Be thorough but efficient. Focus on factual, well-sourced information.
        When you have gathered sufficient information, present a well-structured final summary
        with sections and source citations.
        """,
};

// --- Get the research topic ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a topic to research: ");
    topic = Console.ReadLine()?.Trim() ?? "";
}

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}");
Console.WriteLine(new string('─', 50));

// --- Run the agent ---
var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
        Tools = [.. tools],
    },
};

Console.WriteLine("\nAgent is researching... (this may take a minute)\n");

var response = new StringBuilder();
await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
        response.Append(message.Text);
    }
}

Console.WriteLine();
Console.WriteLine(new string('─', 50));

// --- Show notes summary ---
var allNotes = noteTool.GetAllNotes();
if (allNotes.Count > 0)
{
    Console.WriteLine($"\n📝 Research notes collected: {allNotes.Count}");
    foreach (var note in allNotes)
    {
        Console.WriteLine($"  [{note.Topic}] {note.Content[..Math.Min(80, note.Content.Length)]}...");
    }
}

Console.WriteLine("\nResearch complete.");

