            ? _notes
            : _notes.Where(n => n.Topic.Contains(topicFilter, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return topicFilter is null
                ? "No notes saved yet."
                : $"No notes found for topic '{topicFilter}'.";
