using System.ComponentModel;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides a web search tool that queries DuckDuckGo and returns results.
/// </summary>
public sealed partial class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
    }

    [Description("Searches the web for information on a given query. Returns a list of result titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        try
        {
            var encodedQuery = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";

            var response = await _httpClient.GetStringAsync(url);
            var results = ParseSearchResults(response, maxResults);

            if (results.Count == 0)
            {
                return $"No results found for: {query}";
            }

            return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Fetches the text content of a web page given its URL. Use this to read full articles found via search.")]
    public async Task<string> FetchPageContentAsync(
        [Description("The URL of the web page to fetch")] string url,
        [Description("Maximum characters of content to return (default 3000)")] int maxLength = 3000)
    {
        try
        {
            var response = await _httpClient.GetStringAsync(url);

            // Strip HTML tags and extract text
            var text = StripHtmlTags(response);
            text = CollapseWhitespace(text).Trim();

            if (text.Length > maxLength)
            {
                text = text[..maxLength] + "\n\n[Content truncated]";
            }

            return string.IsNullOrWhiteSpace(text)
                ? "Could not extract meaningful content from this page."
                : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseSearchResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();
        var matches = ResultPattern().Matches(html);

        foreach (Match match in matches)
        {
            if (results.Count >= maxResults)
                break;

            var resultUrl = match.Groups[1].Value;
            var title = StripHtmlTags(match.Groups[2].Value).Trim();
            var snippet = "";

            // Find the snippet associated with this result
            var snippetMatch = SnippetPattern().Match(html, match.Index);
            if (snippetMatch.Success)
            {
                snippet = StripHtmlTags(snippetMatch.Groups[1].Value).Trim();
            }

            if (!string.IsNullOrWhiteSpace(title) && resultUrl.StartsWith("http"))
            {
                results.Add(new SearchResult(title, resultUrl, snippet));
            }
        }

        return results;
    }

    private static string StripHtmlTags(string html)
    {
        var text = HtmlTagPattern().Replace(html, " ");
        text = text.Replace("&amp;", "&")
                   .Replace("&lt;", "<")
                   .Replace("&gt;", ">")
                   .Replace("&quot;", "\"")
                   .Replace("&#39;", "'")
                   .Replace("&nbsp;", " ");
        return text;
    }

    private static string CollapseWhitespace(string text) =>
        WhitespacePattern().Replace(text, " ");

    [GeneratedRegex(@"<a[^>]*class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex ResultPattern();

    [GeneratedRegex(@"<a[^>]*class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex SnippetPattern();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTagPattern();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespacePattern();

    private sealed record SearchResult(string Title, string Url, string Snippet);
}

