@@ -1,0 +1,67 @@
+using System.ComponentModel;
+using System.Text;
+using System.Text.Json;
+
+namespace ResearchAgent.Tools;
+
+/// <summary>
+/// Provides a note-taking tool for the agent to organize research findings.
+/// </summary>
+public sealed class NoteTool
+{
+    private readonly List<Note> _notes = [];
+
+    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
+    public string SaveNote(
+        [Description("A short label or category for the note (e.g., 'definition', 'key finding', 'statistic')")] string topic,
+        [Description("The content of the note")] string content,
+        [Description("The source URL where this information was found, if available")] string? sourceUrl = null)
+    {
+        var note = new Note(
+            Id: _notes.Count + 1,
+            Topic: topic,
+            Content: content,
+            SourceUrl: sourceUrl,
+            Timestamp: DateTime.UtcNow);
+
+        _notes.Add(note);
+        return $"Note #{note.Id} saved under topic '{topic}'.";
+    }
+
+    [Description("Retrieves all saved research notes, optionally filtered by topic.")]
+    public string GetNotes(
+        [Description("Optional topic filter. If provided, only notes matching this topic are returned.")] string? topicFilter = null)
+    {
+        var filtered = string.IsNullOrWhiteSpace(topicFilter)
+            ? _notes
+            : _notes.Where(n => n.Topic.Contains(topicFilter, StringComparison.OrdinalIgnoreCase)).ToList();
+
+        if (filtered.Count == 0)
+        {
+            return topicFilter is null
+                ? "No notes saved yet."
+                : $"No notes found for topic '{topicFilter}'.";
+        }
+
+        return JsonSerializer.Serialize(filtered, new JsonSerializerOptions { WriteIndented = true });
+    }
+
+    [Description("Returns a count of all saved notes grouped by topic.")]
+    public string GetNoteSummary()
+    {
+        if (_notes.Count == 0)
+            return "No notes saved yet.";
+
+        var summary = _notes
+            .GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase)
+            .Select(g => new { Topic = g.Key, Count = g.Count() });
+
+        return JsonSerializer.Serialize(summary, new JsonSerializerOptions { WriteIndented = true });
+    }
+
+    /// <summary>Gets all notes for final summary generation.</summary>
+    public IReadOnlyList<Note> GetAllNotes() => _notes.AsReadOnly();
+
+    public sealed record Note(int Id, string Topic, string Content, string? SourceUrl, DateTime Timestamp);
+}
+

