1. using System.ComponentModel;
2. using System.Text.Json;
3. using System.Text.RegularExpressions;
4. using Microsoft.Extensions.AI;
5. 
6. namespace ResearchAgent.Tools;
7. 
8. /// <summary>
9. /// Provides a web search tool that queries DuckDuckGo and returns results.
10. /// </summary>
11. public sealed partial class WebSearchTool
12. {
13.     private readonly HttpClient _httpClient;
14. 
15.     public WebSearchTool(HttpClient httpClient)
16.     {
17.         _httpClient = httpClient;
18.         _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
19.             "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
20.     }
21. 
22.     [Description("Searches the web for information on a given query. Returns a list of result titles, URLs, and snippets.")]
23.     public async Task<string> SearchWebAsync(
24.         [Description("The search query string")] string query,
25.         [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
26.     {
27.         try
28.         {
29.             var encodedQuery = Uri.EscapeDataString(query);
30.             var url = $"https://html.duckduckgo.com/html/?q={encodedQuery}";
31. 
32.             var response = await _httpClient.GetStringAsync(url);
33.             var results = ParseSearchResults(response, maxResults);
34. 
35.             if (results.Count == 0)
36.             {
37.                 return $"No results found for: {query}";
38.             }
39. 
40.             return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
41.         }
42.         catch (Exception ex)
43.         {
44.             return $"Search failed: {ex.Message}. Try rephrasing the query.";
45.         }
46.     }
47. 
48.     [Description("Fetches the text content of a web page given its URL. Use this to read full articles found via search.")]
49.     public async Task<string> FetchPageContentAsync(
50.         [Description("The URL of the web page to fetch")] string url,
51.         [Description("Maximum characters of content to return (default 3000)")] int maxLength = 3000)
52.     {
53.         try
54.         {
55.             var response = await _httpClient.GetStringAsync(url);
56. 
57.             // Strip HTML tags and extract text
58.             var text = StripHtmlTags(response);
59.             text = CollapseWhitespace(text).Trim();
60. 
61.             if (text.Length > maxLength)
62.             {
63.                 text = text[..maxLength] + "\n\n[Content truncated]";
64.             }
65. 
66.             return string.IsNullOrWhiteSpace(text)
67.                 ? "Could not extract meaningful content from this page."
68.                 : text;
69.         }
70.         catch (Exception ex)
71.         {
72.             return $"Failed to fetch page: {ex.Message}";
73.         }
74.     }
75. 
76.     private static List<SearchResult> ParseSearchResults(string html, int maxResults)
77.     {
78.         var results = new List<SearchResult>();
79.         var matches = ResultPattern().Matches(html);
80. 
81.         foreach (Match match in matches)
82.         {
83.             if (results.Count >= maxResults)
84.                 break;
85. 
86.             var resultUrl = match.Groups[1].Value;
87.             var title = StripHtmlTags(match.Groups[2].Value).Trim();
88.             var snippet = "";
89. 
90.             // Find the snippet associated with this result
91.             var snippetMatch = SnippetPattern().Match(html, match.Index);
92.             if (snippetMatch.Success)
93.             {
94.                 snippet = StripHtmlTags(snippetMatch.Groups[1].Value).Trim();
95.             }
96. 
97.             if (!string.IsNullOrWhiteSpace(title) && resultUrl.StartsWith("http"))
98.             {
99.                 results.Add(new SearchResult(title, resultUrl, snippet));
100.             }
101.         }
102. 
103.         return results;
104.     }
105. 
106.     private static string StripHtmlTags(string html)
107.     {
108.         var text = HtmlTagPattern().Replace(html, " ");
109.         text = text.Replace("&amp;", "&")
110.                    .Replace("&lt;", "<")
111.                    .Replace("&gt;", ">")
112.                    .Replace("&quot;", "\"")
113.                    .Replace("&#39;", "'")
114.                    .Replace("&nbsp;", " ");
115.         return text;
116.     }
117. 
118.     private static string CollapseWhitespace(string text) =>
119.         WhitespacePattern().Replace(text, " ");
120. 
121.     [GeneratedRegex(@"<a[^>]*class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
122.     private static partial Regex ResultPattern();
123. 
124.     [GeneratedRegex(@"<a[^>]*class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
125.     private static partial Regex SnippetPattern();
126. 
127.     [GeneratedRegex(@"<[^>]+>")]
128.     private static partial Regex HtmlTagPattern();
129. 
130.     [GeneratedRegex(@"\s+")]
131.     private static partial Regex WhitespacePattern();
132. 
133.     private sealed record SearchResult(string Title, string Url, string Snippet);
134. }
